export const libraryKitabs: LibraryBook[] = RAW_KITABS.map(
  ([serial, title, volumes, author, publisher, category, arabicCategory], index) => ({
    id: `kitab-${index + 1}`,
    type: 'kitab',
    code: serial || undefined,
    title,
    arabicTitle: title,
    author: author || undefined,
    volumes: volumes || undefined,
    publisher: publisher || undefined,
    category,
    arabicCategory,
  }),
)

export const libraryGeneralBooks: LibraryBook[] = RAW_BOOKS.map(
  ([code, title, author, category], index) => ({
    id: `book-${index + 1}`,
    type: 'book',
    code: code || undefined,
    title,
    author: author || undefined,
    category,
  }),
)

export const libraryBooks: LibraryBook[] = [
  ...libraryKitabs,
  ...libraryGeneralBooks,
]

export const KITABS_COUNT = libraryKitabs.length
export const BOOKS_COUNT = libraryGeneralBooks.length
